 "content": "def transform(grid):
    """Fill between aligned occurrences of the non-background marker color."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = [v for row in grid for v in row if v != bg]
    if not colors:
        return [row[:] for row in grid]
    # In these puzzles the sparse line markers use one color; infer it rather
    # than assuming a fixed marker value.
    marker = Counter(colors).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == marker]
        if len(cs) >= 2:
            for c in range(min(cs), max(cs) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == marker]
        if len(rs) >= 2:
            for r in range(min(rs), max(rs) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

