 "content": "def transform(grid):
    """Fill short gaps between marker cells aligned in a row or column."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = Counter(v for row in grid for v in row if v != bg).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Complete gaps between successive marks, but leave long empty stretches alone.
    max_gap = 5
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(cs, cs[1:]):
            if b - a - 1 <= max_gap:
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rs, rs[1:]):
            if b - a - 1 <= max_gap:
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out

if __name__ == "__main__":
